import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject.
 * Since the implementation provided always throws a JsonGenerationException,
 * the tests focus on verifying this behavior for different input scenarios.
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen0Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // JsonGenerator is abstract and has a protected constructor.
        // We use Mockito to create a mock instance to test the concrete method implementation.
        jsonGenerator = mock(JsonGenerator.class, Mockito.withSettings()
                .useConstructor()
                .defaultAnswer(Mockito.CALLS_REAL_METHODS));
    }

    @Test
    public void testWriteEmbeddedObject_WithNonNullObject_ThrowsException() throws IOException {
        Object testObject = new Object();
        try {
            jsonGenerator.writeEmbeddedObject(testObject);
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getMessage());
            // Verify it's the correct exception type
            Assert.assertTrue(e instanceof JsonGenerationException);
        }
    }

    @Test
    public void testWriteEmbeddedObject_WithNullObject_ThrowsException() throws IOException {
        try {
            jsonGenerator.writeEmbeddedObject(null);
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getMessage());
        }
    }

    @Test
    public void testWriteEmbeddedObject_WithStringType_ThrowsException() throws IOException {
        String testString = "test";
        try {
            jsonGenerator.writeEmbeddedObject(testString);
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getMessage());
        }
    }

    @Test
    public void testWriteEmbeddedObject_WithInteger_ThrowsException() throws IOException {
        Integer testInt = 123;
        try {
            jsonGenerator.writeEmbeddedObject(testInt);
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getMessage());
        }
    }
}
